PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE registrations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  group_id TEXT UNIQUE NOT NULL,
  total_attendees INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, edit_token TEXT, is_waitlist INTEGER NOT NULL DEFAULT 0);
CREATE TABLE attendees (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ticket_id TEXT UNIQUE NOT NULL,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  phone TEXT,
  registration_group_id TEXT NOT NULL,
  giver_army INTEGER NOT NULL DEFAULT 0,
  giver_army_tenure TEXT,
  checked_in INTEGER NOT NULL DEFAULT 0,
  checked_in_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')), photo_consent INTEGER NOT NULL DEFAULT 1, is_waitlist INTEGER NOT NULL DEFAULT 0, cancelled INTEGER NOT NULL DEFAULT 0, cancelled_at TEXT, is_giver_army INTEGER NOT NULL DEFAULT 0, media_consent INTEGER NOT NULL DEFAULT 0, waitlist_timestamp TEXT, updated_at TEXT, vip_cocktail INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (registration_group_id) REFERENCES registrations(group_id)
);
CREATE TABLE event_settings (
  key   TEXT PRIMARY KEY,
  value TEXT
);
CREATE TABLE email_templates (
  slug       TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  subject    TEXT NOT NULL,
  body       TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_attendees_email ON attendees(email);
CREATE INDEX idx_attendees_ticket_id ON attendees(ticket_id);
CREATE INDEX idx_attendees_group_id ON attendees(registration_group_id);
CREATE INDEX idx_attendees_checked_in ON attendees(checked_in);
CREATE UNIQUE INDEX idx_attendees_email_active
  ON attendees(email) WHERE cancelled = 0;
CREATE INDEX idx_attendees_is_waitlist  ON attendees(is_waitlist);
CREATE INDEX idx_attendees_giver_army   ON attendees(is_giver_army);
CREATE INDEX idx_attendees_created      ON attendees(created_at);
