INSERT INTO "event_settings" ("key","value") VALUES('event_name','Celebrate');
INSERT INTO "event_settings" ("key","value") VALUES('event_year','2026');
INSERT INTO "event_settings" ("key","value") VALUES('event_tagline','An Evening of Celebration & Generosity');
INSERT INTO "event_settings" ("key","value") VALUES('event_description','Join us for an unforgettable evening celebrating the power of generosity. Dinner, live entertainment, inspiring stories, and community.');
INSERT INTO "event_settings" ("key","value") VALUES('gala_date','2026-11-07');
INSERT INTO "event_settings" ("key","value") VALUES('start_time','19:00');
INSERT INTO "event_settings" ("key","value") VALUES('end_time','22:00');
INSERT INTO "event_settings" ("key","value") VALUES('time_zone','America/New_York');
INSERT INTO "event_settings" ("key","value") VALUES('venue_name','DoubleTree by Hilton Orlando Theme Park Resort');
INSERT INTO "event_settings" ("key","value") VALUES('venue_address','10100 International Drive');
INSERT INTO "event_settings" ("key","value") VALUES('venue_city','Orlando');
INSERT INTO "event_settings" ("key","value") VALUES('venue_state','FL');
INSERT INTO "event_settings" ("key","value") VALUES('dress_code','Formal/ Cocktail');
INSERT INTO "event_settings" ("key","value") VALUES('parking_info','Parking on premises. Discounted fee of $10 per car for per night');
INSERT INTO "event_settings" ("key","value") VALUES('arrival_info','Doors open 15 minutes before start. Please arrive early for check-in at the main lobby.');
