INSERT INTO "event_settings" ("key","value") VALUES('faq_json','[{"q":"What is the dress code?","a":"Black Tie Optional. Dress to celebrate."},{"q":"Is parking available?","a":"Yes — on premises for a discounted rate of $10 per night."},{"q":"What time should I arrive?","a":"Doors open 15 minutes before start time. Please arrive early for check-in."},{"q":"Can I bring a guest?","a":"Yes — you can register yourself plus one guest."},{"q":"What should I expect?","a":"A beautiful evening with dinner, live entertainment, inspiring stories, and celebration."},{"q":"What is the Giver Army?","a":"The Giver Army is a community of generous people who give monthly through GiveSendGo to support causes they believe in. Members are the heart of the GiveSendGo mission."},{"q":"Why should I join the Giver Army?","a":"Giver Army members are part of an incredible community making a real difference. You get exclusive access to events like the VIP Cocktail Hour, direct updates from campaigns you support, and the joy of consistent, impactful giving."},{"q":"How do I get VIP access?","a":"VIP Cocktail Hour access (6:00–6:45 PM) is exclusive to Giver Army members. Simply select \"Yes\" when asked if you are part of the Giver Army during registration, and check the box to attend the VIP Cocktail Hour. Not a member yet? You can join at giverarmy.com."}]');
INSERT INTO "email_templates" ("slug","name","subject","body","updated_at") VALUES('confirmation','Confirmation Email','You''re in for {{event_name}} — {{event_date}}',replace('Hi {{first_name}},\n\nYou''re all set for {{event_name}}!\n\nWhen: {{event_date}} at {{event_time}}\nWhere: {{location}}\nDress code: {{dress_code}}\n\nYour ticket QR code is attached below — please present it at the door.\n\n{{qr_code}}\n\nNeed to update your registration? {{edit_link}}\n\nWe can''t wait to celebrate with you.\n\n— The GiveSendGo and GiveSendGo Charities ','\n',char(10)),'2026-06-05 01:50:58');
INSERT INTO "email_templates" ("slug","name","subject","body","updated_at") VALUES('reminder_1week','One Week Reminder','{{event_name}} is one week away',replace(replace('Hi {{first_name}},\r\n\r\nJust a friendly reminder — {{event_name}} is just one week away.\r\n\r\nWhen: {{event_date}} at {{event_time}}\r\nWhere: {{location}}\r\nDress code: {{dress_code}}\r\n\r\nPlan your arrival: doors open 30 minutes before start. Complimentary valet is available at the entrance.\r\n\r\n{{qr_code}}\r\n\r\nSee you soon.\r\n\r\n— The GiveSendGo Team','\r',char(13)),'\n',char(10)),'2026-04-14 20:12:29');
INSERT INTO "email_templates" ("slug","name","subject","body","updated_at") VALUES('reminder_24hr','24 Hour Reminder','Tomorrow: {{event_name}}',replace(replace('Hi {{first_name}},\r\n\r\nTomorrow is the big night!\r\n\r\nWhen: {{event_date}} at {{event_time}}\r\nWhere: {{location}}\r\nDress code: {{dress_code}}\r\n\r\nPresent this QR code at the check-in table:\r\n\r\n{{qr_code}}\r\n\r\nParking: valet at the entrance.\r\nArrival: please arrive 15–30 minutes before start.\r\n\r\n— The GiveSendGo Team','\r',char(13)),'\n',char(10)),'2026-04-14 20:12:29');
INSERT INTO "email_templates" ("slug","name","subject","body","updated_at") VALUES('post_event','Post-Event Thank You','Thank you for joining us at {{event_name}}',replace(replace('Hi {{first_name}},\r\n\r\nThank you for making {{event_name}} unforgettable.\r\n\r\nWe''ll be sharing photos and highlights soon. In the meantime, keep the generosity going — there are thousands of campaigns on GiveSendGo ready for your encouragement.\r\n\r\nWith gratitude,\r\n— The GiveSendGo Team','\r',char(13)),'\n',char(10)),'2026-04-14 20:12:29');
INSERT INTO "email_templates" ("slug","name","subject","body","updated_at") VALUES('bulk_update','Bulk Update / Announcement','Update about {{event_name}}',replace(replace('Hi {{first_name}},\r\n\r\n[Write your announcement here.]\r\n\r\n— The GiveSendGo Team','\r',char(13)),'\n',char(10)),'2026-04-14 20:12:29');
